import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type QuickOption = {
  label: string;
  getValue: () => Date;
};

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

const quickOptions: QuickOption[] = [
  { label: 'Сегодня', getValue: () => startOfDay(new Date()) },
  {
    label: 'Вчера',
    getValue: () => {
      const d = startOfDay(new Date());
      d.setDate(d.getDate() - 1);
      return d;
    },
  },
  {
    label: 'Неделя назад',
    getValue: () => {
      const d = startOfDay(new Date());
      d.setDate(d.getDate() - 7);
      return d;
    },
  },
];

interface ReportDatePickerProps {
  onChange?: (value: Date | null) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date | null>(startOfDay(new Date()));

  const handleChange = (value: Date | null) => {
    setSelectedDate(value);
    onChange?.(value);
  };

  const isActiveOption = (option: QuickOption) => {
    if (!selectedDate) return false;
    return startOfDay(option.getValue()).getTime() === startOfDay(selectedDate).getTime();
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-radius-md)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-radius-sm)' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.label}
            active={isActiveOption(option)}
            onClick={() => handleChange(option.getValue())}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selectedDate} onValueChange={handleChange} />
    </div>
  );
}

